# Scientific Data Extractor - runnable demo (JAH-ATK158-000001)
import re, statistics
RANK = 1
SIG = False
SAMPLE = ['12.5 km', '300 m', '45 cm', '8.2 km']
UNIT_SI = {"km": ("m", 1000.0), "m": ("m", 1.0), "cm": ("m", 0.01),
           "kg": ("kg", 1.0), "g": ("kg", 0.001), "s": ("s", 1.0), "ms": ("s", 0.001)}
vals = []
for item in SAMPLE:
    m = re.match(r"\s*([+-]?[\d.]+(?:e[+-]?\d+)?)\s*([a-zA-Z]+)\s*$", item)
    if not m:
        print("unparseable:", item); continue
    v, u = float(m.group(1)), m.group(2)
    si_unit, factor = UNIT_SI.get(u, (u, 1.0))
    vals.append({"raw": item.strip(), "value": v, "unit": u, "si": v*factor, "si_unit": si_unit})
for r in vals:
    print("%-12s -> %.4g %s" % (r["raw"], r["si"], r["si_unit"]))
if RANK >= 2 and vals:
    by_unit = {}
    for r in vals: by_unit.setdefault(r["si_unit"], []).append(r["si"])
    for u, xs in by_unit.items():
        print("unit %s: n=%d mean=%.4g std=%.4g" % (u, len(xs), statistics.mean(xs), statistics.pstdev(xs) if len(xs) > 1 else 0.0))
if RANK >= 3 and vals:
    all_si = [r["si"] for r in vals if r["si_unit"] == vals[0]["si_unit"]]
    if len(all_si) > 2:
        mu, sd = statistics.mean(all_si), statistics.pstdev(all_si)
        out = [r["raw"] for r in vals if r["si_unit"] == vals[0]["si_unit"] and abs(r["si"]-mu) > 2*sd]
        print("outliers (>2sd):", out if out else "none")
if SIG:
    print("Signature lineage stamp: JAH-SIG-SCI-" + "JAH-ATK158-000001")
print("record:", "JAH-ATK158-000001", "OK")

